class Solution:
    def minLength(self, s: str) -> int:
        stack = []

        for char in s:
            if char == 'B' and stack and stack[-1] == 'A':
                stack.pop()  # Remove "AB"
            elif char == 'D' and stack and stack[-1] == 'C':
                stack.pop()  # Remove "CD"
            else:
                stack.append(char)

        return len(stack)

